export type Product = {
  sku: string;
  name: string;
  priceCents: number;
};

export function formatProduct(product: Product): string {
  const dollars = (product.priceCents / 100).toFixed(2);
  return `${product.sku} ${product.name} $${dollars}`;
}

const products: Product[] = [
  { sku: "MUG-001", name: "Ceramic Mug", priceCents: 1299 },
  { sku: "TEE-042", name: "Logo T-Shirt", priceCents: 2450 },
  { sku: "PEN-007", name: "Gel Pen", priceCents: 199 },
];

for (const product of products) {
  console.log(formatProduct(product));
}

steps.body:
Put `?` after a property name to make it optional. Reading an optional property gives its type plus `undefined`, so supply a default with `??`:

```typescript
type Profile = {
  name: string;
  bio?: string;
};

const linus: Profile = { name: "Linus" };
const bio = linus.bio;
//    ^? const bio: string | undefined
console.log(bio ?? "(no bio)"); // (no bio)
```

Put `readonly` before a property that must not change once the object exists, like an id. Assigning to it is a type error (TS2540). At runtime it is still an ordinary property: only the checker stops the assignment.

This course turns on `exactOptionalPropertyTypes`, so optional means "may be missing", not "may be `undefined`". To leave a value out, leave the key out. Writing `bio: undefined` is an error (TS2375) unless the type says `bio?: string | undefined`. The difference shows up at runtime too, because `Object.keys` and the `in` operator see a key that holds `undefined`.

examples.code:
type Profile = {
  name: string;
  bio?: string;
};

function describeProfile(profile: Profile): string {
  return `${profile.name}: ${profile.bio ?? "(no bio)"}`;
}

const ada: Profile = { name: "Ada", bio: "Wrote the first program" };
const linus: Profile = { name: "Linus" };

console.log(describeProfile(ada));
console.log(describeProfile(linus));

type Account = {
  readonly id: number;
  owner: string;
};

const account: Account = { id: 1, owner: "Ada" };
account.owner = "Grace";
account.id = 2;
console.log(`${account.id}: ${account.owner}`);

type Profile = {
  name: string;
  bio?: string;
};

const ada: Profile = { name: "Ada", bio: undefined };
console.log(ada.name);

examples.explanation:
With `exactOptionalPropertyTypes`, `bio?: string` means the key is either missing or holds a string. `bio: undefined` is neither, so `tsc` reports TS2375. There are two fixes:

- Leave the key out: `{ name: "Ada" }`. This is the usual one.
- Widen the type to `bio?: string | undefined`, when your data really holds explicit `undefined` values.

With the wider type, the key exists even though its value is `undefined`:

```typescript
type Profile = {
  name: string;
  bio?: string | undefined;
};

const ada: Profile = { name: "Ada", bio: undefined };
console.log(Object.keys(ada).join(", ")); // name, bio
```

